import { traverseTree } from '../../exported-utils';
export class SelectableTree {
    constructor(tree, disabledItems, leafNodeStatus) {
        //Holds the values for the check
        this.parentNodeStatus = {};
        //Holds the true/false values for the leaves
        //For this file, a leaf is defined as an node with no children.
        this.leafNodeStatus = {};
        this.treeNodeParents = {};
        this.disabledItems = {};
        if (disabledItems) {
            this.disabledItems = disabledItems;
        }
        if (leafNodeStatus != null) {
            this.leafNodeStatus = leafNodeStatus;
        }
        this.setTreeNodes(tree);
    }
    setTreeNodes(treeNodes) {
        this.treeNodes = treeNodes;
        this.treeNodeParents = {};
        //Populate the parent map.
        //Also check for duplicates.
        const idsMap = {};
        traverseTree(this.treeNodes, (treeNode, parentNode) => {
            if (idsMap[treeNode.id]) {
                console.error(`It appears there is a duplicate id: ${treeNode.id} in your tree.`);
            }
            idsMap[treeNode.id] = true;
            if (parentNode != null) {
                this.treeNodeParents[treeNode.id] = parentNode;
            }
        });
    }
    setDisabledItems(value) {
        this.disabledItems = value;
        this.rebuildParentNodeStatus();
    }
    /**
     * Sets and individual status of the tree.
     * @param treeNode
     * @param isChecked
     */
    setStatus(treeNode, isChecked) {
        //set status down the tree
        this.setStatusDownTheTree(treeNode, isChecked);
        //set status up the tree
        this.setStatusUpTheTree(treeNode);
    }
    //Sets the status of the tree Node, and all of it's descendants to the value isChecked.
    setStatusDownTheTree(treeNode, isChecked) {
        if (this.disabledItems[treeNode.id]) {
            //Disabled nodes are treated like they do not exist.
            return;
        }
        if (treeNode.children != null) {
            this.parentNodeStatus[treeNode.id] = isChecked;
            for (const childNode of treeNode.children) {
                this.setStatusDownTheTree(childNode, isChecked);
            }
        }
        else {
            this.leafNodeStatus[treeNode.id] = isChecked;
        }
    }
    //Sets the value of all of the treeNode and all of the
    //treeNode's ancestors to the proper status based on
    //the status of each ancestor's direct children.
    setStatusUpTheTree(treeNode) {
        if (treeNode == null || this.disabledItems[treeNode.id]) {
            return;
        }
        if (treeNode.children == null) {
            //If a leaf node is passed in, set the status of the parent.
            this.setStatusUpTheTree(this.getParent(treeNode));
            return;
        }
        let checked = 0;
        let unchecked = 0;
        let isIndeterminate = false;
        loopOnChildren: for (const childNode of treeNode.children) {
            if (this.disabledItems[childNode.id]) {
                continue;
            }
            if (childNode.children != null) {
                const status = this.parentNodeStatus[childNode.id] || false;
                if (status === true) {
                    checked++;
                }
                else if (status === false) {
                    unchecked++;
                }
                else {
                    //status must be indeterminate
                    isIndeterminate = true;
                    break loopOnChildren; //We are done looping.
                }
            }
            else {
                if (this.leafNodeStatus[childNode.id]) {
                    checked++;
                }
                else {
                    unchecked++;
                }
            }
            if (checked > 0 && unchecked > 0) {
                //status must be indeterminate
                isIndeterminate = true;
                break loopOnChildren; //We are done looping.
            }
        }
        if (isIndeterminate) {
            this.parentNodeStatus[treeNode.id] = 'indeterminate';
        }
        else if (checked > 0) {
            this.parentNodeStatus[treeNode.id] = true;
        }
        else if (unchecked > 0) {
            this.parentNodeStatus[treeNode.id] = false;
        }
        const parentNode = this.treeNodeParents[treeNode.id];
        if (parentNode != null) {
            this.setStatusUpTheTree(parentNode);
        }
    }
    isNodeSelected(treeNode) {
        if (treeNode.children != null) {
            return this.parentNodeStatus[treeNode.id] === true;
        }
        else {
            return this.leafNodeStatus[treeNode.id];
        }
    }
    isNodeIndeterminate(treeNode) {
        if (treeNode.children != null) {
            return this.parentNodeStatus[treeNode.id] === 'indeterminate';
        }
        else {
            return false; //leaf nodes can only be true or false
        }
    }
    setLeafNodeStatusMap(value) {
        //Set the new leaf statuses
        this.leafNodeStatus = value;
        this.rebuildParentNodeStatus();
    }
    rebuildParentNodeStatus() {
        for (const childNode of this.treeNodes) {
            this.calculateNodeStatus(childNode);
        }
    }
    getParent(treeNode) {
        return this.treeNodeParents[treeNode.id];
    }
    /**
     * Gets the node status of treeNode.  If treeNode is a parent, it will
     * also set the status in this.parentNodeStatus[treeNode.id]
     *
     * NOTE: The first time this method was written, there were performance issues so be careful
     * when modifying this.
     */
    calculateNodeStatus(treeNode) {
        if (treeNode.children == null) {
            return this.leafNodeStatus[treeNode.id] || false;
        }
        else {
            let nodes = 0;
            let checkedNodes = 0;
            let uncheckedNodes = 0;
            //Since this method not only gets the state, it also sets it,
            //We have to loop over all of the nodes and not short circuit
            //even if we know the state must be indeterminate.
            for (const childNode of treeNode.children) {
                const childStatus = this.calculateNodeStatus(childNode);
                if (this.disabledItems[childNode.id]) {
                    continue;
                }
                nodes++;
                if (childStatus === true) {
                    checkedNodes++;
                }
                else if (childStatus === false) {
                    uncheckedNodes++;
                }
            }
            if (nodes === uncheckedNodes) {
                //This is also the correct case for when nodes === 0.
                this.parentNodeStatus[treeNode.id] = false;
            }
            else if (nodes === checkedNodes) {
                this.parentNodeStatus[treeNode.id] = true;
            }
            else {
                this.parentNodeStatus[treeNode.id] = 'indeterminate';
            }
            return this.parentNodeStatus[treeNode.id];
        }
    }
}
